PROGRAM conveyor_ctrl
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    GuardClosed : BOOL;
    Fault : BOOL;
END_VAR
VAR_OUTPUT
    Conveyor : BOOL;
END_VAR
VAR
    Running : BOOL;
END_VAR

IF StopPB OR (NOT GuardClosed) OR Fault THEN
    Running := FALSE;
ELSIF StartPB AND GuardClosed AND (NOT Fault) THEN
    Running := TRUE;
END_IF;

Conveyor := Running;

END_PROGRAM

