PROGRAM elevator
VAR_INPUT
    CallUp    : BOOL;
    CallDown  : BOOL;
    DoorClosed: BOOL;
    AtTop     : BOOL;
    AtBottom  : BOOL;
END_VAR

VAR_OUTPUT
    MotorUp   : BOOL;
    MotorDown : BOOL;
END_VAR

VAR
    State     : INT;
END_VAR

    MotorUp   := FALSE;
    MotorDown := FALSE;

    CASE State OF

        0:
            IF AtBottom THEN
                MotorUp   := FALSE;
                MotorDown := FALSE;
            END_IF;
            IF CallUp AND DoorClosed AND NOT AtTop THEN
                State := 1;
            END_IF;

        1:
            IF AtTop THEN
                MotorUp   := FALSE;
                MotorDown := FALSE;
                State     := 2;
            ELSIF DoorClosed AND NOT AtTop THEN
                MotorUp   := TRUE;
                MotorDown := FALSE;
            ELSE
                MotorUp   := FALSE;
                MotorDown := FALSE;
            END_IF;

        2:
            IF AtTop THEN
                MotorUp   := FALSE;
