END_VAR

VAR CONSTANT
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    LIQ_MIN : INT := 10;
END_VAR

VAR
    ReactTimer : TON;
END_VAR

IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
    ReactTimer(IN := FALSE, PT := T#3s);
ELSE
    CASE State OF
        0:
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
            ReactTimer(IN := FALSE, PT := T#3s);
            IF StartBatch THEN
                State := 1;
            END_IF;

        1:
            DrainValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            ReactTimer(IN := FALSE, PT := T#3s);
            IF Level >= LVL_HIGH THEN
                FillValve := FALSE;
                State := 2;
            ELSE
                FillValve := TRUE;
            END_IF;

        2:
            FillValve := FALSE;
            DrainValve := FALSE;
            ReactTimer(IN := FALSE, PT := T#3s);
            IF Level >= LIQ_MIN THEN
                Heater := TRUE;
                Agitator := TRUE;
            ELSE
                Heater := FALSE;
                Agitator := FALSE;
            END_IF;
            IF Temp >= TEMP_SET AND Level >= LIQ_MIN THEN
                State := 3;
            END_IF;

        3:
            FillValve := FALSE;
            DrainValve := FALSE;
            IF Level >= LIQ_MIN THEN
                Heater := TRUE;
                Agitator := TRUE;
                ReactTimer(IN := TRUE, PT := T#3s);
            ELSE
                Heater := FALSE;
                Agitator := FALSE;
                ReactTimer(IN := FALSE, PT := T#3s);
            END_IF;
            IF ReactTimer.Q THEN
                Heater := FALSE;
                Agitator := FALSE;
                ReactTimer(IN := FALSE, PT := T#3s);
                State := 4;
            END_IF;

        4:
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            ReactTimer(IN := FALSE, PT := T#3s);
            IF Level <= LVL_LOW THEN
                DrainValve := FALSE;
                State := 0;
            ELSE
                DrainValve := TRUE;
            END_IF;

        ELSE
            State := 0;
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
            ReactTimer(IN := FALSE, PT := T#3s);
    END_CASE;

    IF Level < LIQ_MIN THEN
        Heater := FALSE;
        Agitator := FALSE;
    END_IF;

    IF FillValve AND DrainValve THEN
        FillValve := FALSE;
        DrainValve := FALSE;
    END_IF;
END_IF;

