PROGRAM garage
VAR_INPUT
    EntrySensor : BOOL;
    ExitSensor  : BOOL;
    EntryReq    : BOOL;
END_VAR

VAR_OUTPUT
    FullSign         : BOOL;
    EntryBarrierOpen : BOOL;
END_VAR

VAR
    Count     : INT;
    PrevEntry : BOOL;
    PrevExit  : BOOL;
END_VAR

VAR CONSTANT
    CAP : INT := 3;
END_VAR

IF (EntrySensor = TRUE) AND (PrevEntry = FALSE) THEN
    IF Count < CAP THEN
        Count := Count + 1;
    END_IF;
END_IF;

IF (ExitSensor = TRUE) AND (PrevExit = FALSE) THEN
    IF Count > 0 THEN
        Count := Count - 1;
    END_IF;
END_IF;

PrevEntry := EntrySensor;
PrevExit  := ExitSensor;

IF Count >= CAP THEN
    FullSign := TRUE;
ELSE
    FullSign := FALSE;
END_IF;

IF (EntryReq = TRUE) AND (FullSign = FALSE) THEN
    EntryBarrierOpen := TRUE;
ELSE
    EntryBarrierOpen := FALSE;
END_IF;

END_PROGRAM

