PROGRAM tank_cycle

VAR_INPUT
    Level : INT;
    StartCycle : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR

VAR
    State : INT;
    HIGH : INT;
    LOW : INT;
END_VAR

HIGH := 90;
LOW := 10;

IF NOT EStop THEN
    State := 0;
    Pump := FALSE;
    Valve := FALSE;
ELSE
    CASE State OF
        0:
            Pump := FALSE;
            Valve := FALSE;
            IF StartCycle AND (Level < HIGH) THEN
                State := 1;
            END_IF;

        1:
            Valve := FALSE;
            IF Level >= HIGH THEN
                Pump := FALSE;
                State := 2;
            ELSE
                Pump := TRUE;
            END_IF;

        2:
            Pump := FALSE;
            IF Level <= LOW THEN
                Valve := FALSE;
                State := 0;
            ELSE
                Valve := TRUE;
            END_IF;

        ELSE
            State := 0;
            Pump := FALSE;
            Valve := FALSE;
    END_CASE;

    IF Pump AND Valve THEN
        Pump := FALSE;
        Valve := FALSE;
        State := 0;
    END_IF;

    IF Pump AND (Level >= HIGH) THEN
        Pump := FALSE;
        State := 0;
    END_IF;

    IF Valve AND (Level <= LOW) THEN
        Valve := FALSE;
        State := 0;
    END_IF;

END_IF;

END_PROGRAM

