        2:
            Fan      := TRUE;
            Fuel     := TRUE;
            Ignition := TRUE;
            TimPurge(IN := FALSE, PT := PT_PURGE);
            TimIgn(IN := TRUE, PT := PT_IGN);
            IF TimIgn.Q THEN
                TimIgn(IN := FALSE, PT := PT_IGN);
                IF Flame THEN
                    State := 3;
                ELSE
                    State := 0;
                END_IF;
            END_IF;

        3:
            Fan      := TRUE;
            Fuel     := TRUE;
            Ignition := FALSE;
            TimPurge(IN := FALSE, PT := PT_PURGE);
            TimIgn(IN := FALSE, PT := PT_IGN);
            IF NOT Flame THEN
                State := 0;
