            State    := 0;
            Fan      := FALSE;
            Fuel     := FALSE;
            Ignition := FALSE;
            TimPurge(IN := FALSE, PT := PT_PURGE);
            TimIgn(IN := FALSE, PT := PT_IGN);

    END_CASE;

    IF Fuel AND NOT Fan THEN
        Fuel     := FALSE;
        Ignition := FALSE;
        State    := 0;
    END_IF;

    IF Ignition AND NOT Fuel THEN
        Ignition := FALSE;
        State    := 0;
