        1:
            Timer2(IN := FALSE, PT := PT_SEQ);
            Timer1(IN := TRUE, PT := PT_SEQ);
            IF Timer1.Q = TRUE THEN
                State := 2;
                Timer1(IN := FALSE, PT := PT_SEQ);
            END_IF;

        2:
            Timer1(IN := FALSE, PT := PT_SEQ);
            Timer2(IN := TRUE, PT := PT_SEQ);
            IF Timer2.Q = TRUE THEN
                State := 3;
                Timer2(IN := FALSE, PT := PT_SEQ);
            END_IF;

        3:
            Timer1(IN := FALSE, PT := PT_SEQ);
            Timer2(IN := FALSE, PT := PT_SEQ);

        ELSE
            State := 0;
            Timer1(IN := FALSE, PT := PT_SEQ);
            Timer2(IN := FALSE, PT := PT_SEQ);
    END_CASE;
END_IF;

C3 := (State = 1) OR (State = 2) OR (State = 3);
C2 := (State = 2) OR (State = 3);
C1 := (State = 3);

END_PROGRAM

PROGRAM conveyor3

VAR_INPUT
    StartPB : BOOL;
    StopPB  : BOOL;
    EStop   : BOOL;
END_VAR

VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR

VAR
    State  : INT;
    Timer1 : TON;
    Timer2 : TON;
END_VAR

VAR CONSTANT
    PT_SEQ : TIME := T#2s;
END_VAR

IF (StopPB = TRUE) OR (EStop = FALSE) THEN
    State  := 0;
    Timer1(IN := FALSE, PT := PT_SEQ);
    Timer2(IN := FALSE, PT := PT_SEQ);
ELSE
    CASE State OF
        0:
            Timer1(IN := FALSE, PT := PT_SEQ);
            Timer2(IN := FALSE, PT := PT_SEQ);
            IF StartPB = TRUE THEN
                State := 1;
            END_IF;

        1:
            Timer2(IN := FALSE, PT := PT_SEQ);
            Timer1(IN := TRUE, PT := PT_SEQ);
            IF Timer1.Q = TRUE THEN
                State := 2;
                Timer1(IN := FALSE, PT := PT_SEQ);
            END_IF;

        2:
            Timer1(IN := FALSE, PT := PT_SEQ);
            Timer2(IN := TRUE, PT := PT_SEQ);
            IF Timer2.Q = TRUE THEN
                State := 3;
                Timer2(IN := FALSE, PT := PT_SEQ);
            END_IF;

        3:
            Timer1(IN := FALSE, PT := PT_SEQ);
            Timer2(IN := FALSE, PT := PT_SEQ);

    ELSE
        State := 0;
        Timer1(IN := FALSE, PT := PT_SEQ);
        Timer2(IN := FALSE, PT := PT_SEQ);
    END_CASE;
END_IF;

C3 := (State = 1) OR (State = 2) OR (State = 3);
C2 := (State = 2) OR (State = 3);
C1 := (State = 3);

IF C1 = TRUE AND C2 = FALSE THEN
    C1 := FALSE;
END_IF;
IF C2 = TRUE AND C3 = FALSE THEN
    C2 := FALSE;
    C1 := FALSE;
END_IF;

END_PROGRAM

PROGRAM dosing
VAR_INPUT
    Trigger : BOOL;
    Reset : BOOL;
END_VAR
VAR_OUTPUT
    Done : BOOL;
END_VAR
VAR
    Count : INT;
    PrevTrigger : BOOL;
END_VAR
VAR CONSTANT
    N : INT := 3;
END_VAR

IF Reset THEN
    Count := 0;
    Done := FALSE;
ELSE
    IF Trigger AND NOT PrevTrigger THEN
        IF Count < N THEN
            Count := Count + 1;
        END_IF;
    END_IF;
    IF Count >= N THEN
        Done := TRUE;
    ELSE
        Done := FALSE;
    END_IF;
END_IF;

PrevTrigger := Trigger;

END_PROGRAM

